 if contract is null or not extensions.jsonb_matches_schema(contract,p_specs) then raise exception 'invalid_category_specifications' using errcode='22023';end if;
 if p_category='cassette' and p_specs->'sprocket_teeth' is not null and p_specs->'sprocket_teeth'<>'null'::jsonb then
  if exists(select 1 from (select value::numeric n,lag(value::numeric)over(order by ordinality) previous from jsonb_array_elements_text(p_specs->'sprocket_teeth') with ordinality) t where n<=previous) then raise exception 'invalid_sprocket_sequence' using errcode='22023';end if;
 end if;
end$$;
